def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find regularly spaced horizontal and vertical grid dividers.
    def divider_rows():
        return [r for r, row in enumerate(grid)
                if all(v in (3, 4, 5) for v in row)
                and sum(v not in (3, 4, 5) for v in row) == 0]

    rs = divider_rows()
    cs = [c for c in range(w)
          if all(grid[r][c] in (3, 4, 5) for r in range(h))]
    if len(rs) < 2 or len(cs) < 2:
        return [[0]]
    # Keep the marked crossings of the grid.
    return [[grid[r][c] for c in cs] for r in rs]
